		filterTextWrapper.setBorder(BORDER_FILTER_TEXT_WRAPPER);
		filterTextWrapper.setBackground(COLOR_FILTER_TEXT_BACKGROUND);
		filterTextWrapper.add(filterText);

		// Setting up text entry field filtering trades totals
