package org.asundr;

import com.google.gson.Gson;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageCapture;
import org.asundr.input.TradeInputManager;
import org.asundr.menu.TradeLookupMenuManager;
import org.asundr.recovery.SaveManager;
import org.asundr.screenshot.ScreenshotUtils;
import org.asundr.trade.TradeManager;
import org.asundr.trade.TradeUtils;
import org.asundr.ui.GuiUtils;
import org.asundr.ui.TradeTrackerPluginPanel;
import org.asundr.utility.CommonUtils;
import org.asundr.utility.StringUtils;

import javax.inject.Inject;
import java.util.Arrays;
import java.util.Collection;

@Slf4j
@PluginDescriptor(
		name = "Trade Tracker",
		description = "Records a searchable history of past trades with players",
		tags = {"trade", "history", "track", "item", "log", "logger", "memory", "lend"}
)
public class TradeTrackerPlugin extends Plugin
{
	private final SaveManager saveManager = new SaveManager();
	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ItemManager itemManager;
	@Inject
	private TradeTrackerConfig config;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ChatboxPanelManager chatboxPanelManager;
	@Inject
	private ChatMessageManager chatMessageManager;
	@Inject
	private EventBus eventBus;
	@Inject
	private Gson gson;
	@Inject
	private SpriteManager spriteManager;
	@Inject
	private ImageCapture imageCapture;
	@Inject
	private DrawManager drawManager;
	@Inject
	private MenuManager menuManager;
	@Inject
	private PluginManager pluginManager;
	@Inject
	private KeyManager keyManager;
	private TradeTrackerPluginPanel mainPanel;
	private NavigationButton navigationButton;
	private TradeLookupMenuManager tradeLookupMenuManager;
	private Collection<Object> eventSubscribers;

	@Provides
	TradeTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TradeTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		CommonUtils.initialize(config, client, clientThread, this, chatboxPanelManager, eventBus, overlayManager, chatMessageManager);
		StringUtils.initialize(gson);
		SaveManager.initialize(configManager);
		TradeUtils.initialize(itemManager);
		ScreenshotUtils.initialize(spriteManager, imageCapture, drawManager, overlayManager, pluginManager);
		TradeInputManager.initialize(keyManager);
		SaveManager.restoreCommonData();
		mainPanel = new TradeTrackerPluginPanel();
		tradeLookupMenuManager = new TradeLookupMenuManager(menuManager);
		eventSubscribers = Arrays.asList(mainPanel, TradeManager.getInstance(), saveManager, tradeLookupMenuManager);
		eventSubscribers.forEach(e -> eventBus.register(e));
		if (!config.getAutoLoadLastProfile())
		{
			SaveManager.forgetActiveHistoryProfile();
		}
		SaveManager.requestRestoreTradeHistory();
		addNavigationButton(mainPanel);
		GuiUtils.initialize(mainPanel, clientToolbar, navigationButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navigationButton);
		eventSubscribers.forEach(e -> eventBus.unregister(e));
		TradeInputManager.shutdown(keyManager);
		tradeLookupMenuManager.shutdown();
		TradeManager.getInstance().shutdown();
		SaveManager.shutdown();
		mainPanel.shutdown();
		ScreenshotUtils.shutdown();
	}

	private void addNavigationButton(final TradeTrackerPluginPanel mainPanel)
	{
		navigationButton = NavigationButton.builder()
				.tooltip("Trade Tracker")
				.icon(CommonUtils.getImageFromName("nav_icon.png"))
				.priority(3)
				.panel(mainPanel)
				.build();
		clientToolbar.addNavigation(navigationButton);
	}

}
